from solution import simplify
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref(x, n):
    a, b = map(int, x.split("/"))
    c, d = map(int, n.split("/"))
    return (a * c) % (b * d) == 0


def frac(a, b):
    return f"{a}/{b}"


# --- explicit spec examples ---
def test_spec_example_1():
    assert simplify("1/5", "5/1") is True


def test_spec_example_2():
    assert simplify("1/6", "2/1") is False


def test_spec_example_3():
    assert simplify("7/10", "10/2") is False


# --- float precision defect: false positive ---
def test_large_near_integer_is_not_whole():
    # 10000000000000001/10000000000000000 = 1.000...0001, not whole
    assert simplify("10000000000000001/10000000000000000", "1/1") is False


def test_large_near_integer_is_not_whole_swapped():
    assert simplify("1/1", "10000000000000001/10000000000000000") is False


def test_large_product_false_positive():
    # (10000000000000001/10000000000000000) * (2/2) is still not whole
    assert simplify("10000000000000001/10000000000000000", "2/2") is False


def test_reciprocal_is_always_whole():
    # 1/n * n/1 == 1 for every n, must be True
    for n in [7, 11, 13, 17, 19, 29, 31, 37, 41, 43, 47, 49, 53, 97, 101]:
        assert simplify(f"1/{n}", f"{n}/1") is True, f"n={n}"


def test_integer_times_integer_is_whole():
    assert simplify("2/1", "3/1") is True
    assert simplify("100/1", "200/1") is True


def test_proper_fractions_not_whole():
    assert simplify("1/2", "1/2") is False  # 1/4
    assert simplify("1/3", "1/3") is False  # 1/9
    assert simplify("2/3", "3/4") is False  # 1/2


def test_cancellation_to_whole():
    assert simplify("2/3", "3/2") is True  # 1
    assert simplify("4/6", "6/4") is True  # 1
    assert simplify("2/4", "4/2") is True  # 2


# --- property tests vs obviously-correct integer reference model ---
@given(
    a=st.integers(min_value=1, max_value=10**6),
    b=st.integers(min_value=1, max_value=10**6),
    c=st.integers(min_value=1, max_value=10**6),
    d=st.integers(min_value=1, max_value=10**6),
)
def test_property_matches_integer_arithmetic_small(a, b, c, d):
    x = frac(a, b)
    n = frac(c, d)
    expected = (a * c) % (b * d) == 0
    assert simplify(x, n) is expected


@given(
    a=st.integers(min_value=10**15, max_value=10**18),
    b=st.integers(min_value=10**15, max_value=10**18),
    c=st.integers(min_value=1, max_value=10**6),
    d=st.integers(min_value=1, max_value=10**6),
)
def test_property_matches_integer_arithmetic_large(a, b, c, d):
    x = frac(a, b)
    n = frac(c, d)
    expected = (a * c) % (b * d) == 0
    assert simplify(x, n) is expected


@given(
    n=st.integers(min_value=1, max_value=200),
)
def test_property_reciprocal_always_true(n):
    assert simplify(f"1/{n}", f"{n}/1") is True


@given(
    a=st.integers(min_value=1, max_value=10**6),
    b=st.integers(min_value=1, max_value=10**6),
    c=st.integers(min_value=1, max_value=10**6),
    d=st.integers(min_value=1, max_value=10**6),
)
def test_property_commutativity(a, b, c, d):
    x = frac(a, b)
    n = frac(c, d)
    assert simplify(x, n) == simplify(n, x)


@given(
    a=st.integers(min_value=1, max_value=10**5),
    b=st.integers(min_value=1, max_value=10**5),
    c=st.integers(min_value=1, max_value=10**5),
    d=st.integers(min_value=1, max_value=10**5),
    k=st.integers(min_value=1, max_value=10**5),
)
def test_property_scaling_invariance(a, b, c, d, k):
    # multiplying num and den of one fraction by k does not change product
    x1 = frac(a, b)
    n1 = frac(c, d)
    x2 = frac(a * k, b * k)
    assert simplify(x1, n1) == simplify(x2, n1)
    n2 = frac(c * k, d * k)
    assert simplify(x1, n1) == simplify(x1, n2)


@given(
    a=st.integers(min_value=1, max_value=10**6),
    b=st.integers(min_value=1, max_value=10**6),
)
def test_property_integer_fraction_times_one(a, b):
    # (a/b) * (b/a) == 1 always whole
    assert simplify(frac(a, b), frac(b, a)) is True


@given(
    a=st.integers(min_value=1, max_value=10**6),
    b=st.integers(min_value=1, max_value=10**6),
    c=st.integers(min_value=1, max_value=10**6),
    d=st.integers(min_value=1, max_value=10**6),
)
def test_property_returns_bool(a, b, c, d):
    r = simplify(frac(a, b), frac(c, d))
    assert r is True or r is False
